draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/4, 50, 0, 2 * Math.PI);
  ctx.fill();

  // rays
  ctx.strokeStyle = 'yellow';
  ctx.lineWidth = 3;
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2, H/4);
    ctx.lineTo(W/2 + 100 * Math.cos(i + t), H/4 + 100 * Math.sin(i + t));
    ctx.stroke();
  }

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(W/2, H - 100, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 80);
  ctx.lineTo(W/2, H - 50); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2 - 30, H - 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2 + 30, H - 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2, H); // leg
  ctx.stroke();

  // bone
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H - 30);
  ctx.lineTo(W/2 + 20, H - 30);
  ctx.stroke();

  // strength indication
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('+' + Math.round(100 * (1 + Math.sin(t))) + '%', W/2, H - 60);

  ctx.restore();
}
